# Dựng shared/landscape.css từ scripts/cozygame/landscape.src.css: bọc trong 2 điều kiện màn ngang (điện thoại thấp; máy tính bảng cảm ứng; màn rộng/máy tính ≥900px rộng, tỉ lệ ≥13:10 → khung phóng to tới 760px). Chạy: python3 scripts/cozygame/mklandscape.py
import os
d=os.path.dirname(os.path.abspath(__file__));src=open(os.path.join(d,"landscape.src.css"),encoding="utf-8").read()
head=src.split("*/",1)[0]+"*/\n";body=src.split("*/",1)[1]
pre="#home>.hl,#home>.hr{display:contents}\n/* nút 📷/📤 gắn vào thanh trên: biểu tượng luôn chính giữa nút */\n#bCam,#bShr{display:grid!important;place-items:center;padding:0!important;line-height:0}#bCam svg,#bShr svg{display:block;margin:0;width:20px;height:20px;flex:none}\n/* màn rất hẹp (mọi hướng): thu nhỏ nút thanh trên để tiêu đề game không bị cắt “…” */\n#play.tight .top>.ib{width:32px;height:32px;min-width:32px;min-height:32px;font-size:3.2cqw}\n/* màn ngang, tên game dài vẫn bị cắt ở cỡ chữ nhỏ nhất: tối đa 2 dòng (landscape.js thêm lớp wrap2) */\n@media (orientation:landscape){#play .top>h1.wrap2{white-space:normal;text-overflow:clip;overflow-wrap:anywhere;line-height:1.05;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}}\n/* màn dọc: tên game được chuyển xuống ngay trên khối nội dung ở giữa màn chọn (bản sao #homeTitle do landscape.js dựng); thanh trên chỉ còn các nút */\n.hometitle{display:none}\n@media (orientation:portrait){#play[data-scr=\"home\"] .hometitle{display:block;margin:0;text-align:center;white-space:normal;text-wrap:balance;overflow-wrap:anywhere;font:400 7.4cqw/1.15 var(--display);color:var(--accent);letter-spacing:.01em}#play[data-scr=\"home\"] .top>h1{visibility:hidden}}\n/* màn dọc: tên game khi đang chơi nằm ngay trên cụm điểm + khung chơi (bản sao #gameTitle do landscape.js dựng) */\n.gametitle{display:none}\n@media (orientation:portrait){#play:not([data-scr=\"home\"]) .scr:not([hidden])>.gametitle{display:block;flex:none;margin:0;text-align:center;white-space:normal;text-wrap:balance;overflow-wrap:anywhere;font:400 5.6cqw/1.15 var(--display);color:var(--accent)}#play:not([data-scr=\"home\"]) .top>h1{visibility:hidden}}\n/* màn dọc, khung chơi vuông/ít cao: gom bảng điểm + khung chơi + nút hành động thành một cụm ở giữa màn hình thay vì dính mép trên/dưới (--ar = cao/rộng của canvas, do landscape.js đặt) */\n@media (orientation:portrait){#play #game{justify-content:center;gap:3cqw}#play #cvw{flex:0 1 calc(92cqw*var(--ar,1.1));min-height:0}}\n"
out=head+pre+"@media (orientation:landscape) and (max-height:700px) and (min-width:560px),(orientation:landscape) and (pointer:coarse) and (max-height:900px) and (min-width:800px),(orientation:landscape) and (min-width:900px) and (min-aspect-ratio:13/10){\n"+body.strip()+"\n}\n"
open(os.path.join(d,"..","..","shared","landscape.css"),"w",encoding="utf-8").write(out);print("ok",len(out))
